"""Native bookmark editing and isolated private-window storage observations."""
import json
from pathlib import Path
from profile import history_urls

def run(c):
 def bookmark_rows():
  path=c.profile/'Default/Bookmarks'
  if not path.exists():return []
  def walk(node):
   yield node
   for child in node.get('children',[]):yield from walk(child)
  return [node for root in json.loads(path.read_text())['roots'].values() for node in walk(root) if node.get('type')=='url']
 def control(name,role='button',description=None):
  rows=c.accessibility.snapshot();(c.out/'bookmark-controls.json').write_text(json.dumps(rows,indent=2));matches=[row for row in rows if row.get('name')==name and row.get('role')==role and row.get('pid')==c.main['pid'] and row.get('states',{}).get('showing') and (description is None or row.get('description')==description)];assert len(matches)<=1,(name,matches);return matches[0] if matches else None
 def activate(name,description=None):row=c.wait(lambda:control(name,description=description),'actual bookmark '+name);c.accessibility.focus(row);c.key('-k','space')
 normal=c.server.origin+'/page?visit=normal';c.navigate(normal);c.wait(lambda:c.evaluate('location.href')==normal,'normal history navigation');c.key('-M','ctrl','-k','d','-m','ctrl');c.wait(lambda:control('Done'),'actual bookmark editor');c.capture('bookmark-add.png');activate('Done');added=c.wait(lambda:next((row for row in bookmark_rows() if row.get('url')==normal),None),'actual bookmark persisted');c.checks.append('Native bookmark add commits exact current URL through actual editor and profile provider')
 c.key('-M','ctrl','-k','d','-m','ctrl');entry=c.wait(lambda:control('Bookmark name','entry'),'actual bookmark name editor');c.accessibility.focus(entry);c.key('-M','ctrl','-k','a','-m','ctrl');c.key('Disposable bookmark');activate('Done');edited=c.wait(lambda:next((row for row in bookmark_rows() if row.get('id')==added['id'] and row.get('name')=='Disposable bookmark'),None),'captured bookmark edit persists');c.checks.append('Native bookmark editor changes same bookmark identity and preserves exact URL')
 c.key('-M','ctrl','-k','d','-m','ctrl');activate('Remove');c.wait(lambda:all(row.get('id')!=added['id'] for row in bookmark_rows()),'captured bookmark removal');c.checks.append('Native bookmark Remove deletes captured bookmark without direct store mutation')
 def history_ui():return c.evaluate("(()=>{const roots=[document];while(roots.length){const root=roots.shift();const list=root.querySelector('history-list');if(list)return list.historyData_?.flatMap(row=>[row.url,...Object.keys(row.allTimestamps||{}).filter(value=>value.startsWith('http'))])||[];for(const node of root.querySelectorAll('*'))if(node.shadowRoot)roots.push(node.shadowRoot);}return null;})()")
 c.navigate('brave://history');c.wait(lambda:normal in (history_ui() or []),'normal visit in actual history provider UI');c.capture('normal-history.png');c.navigate(normal);c.wait(lambda:c.evaluate('location.href')==normal,'return to normal page for storage')
 c.click_page('#set-marker');assert c.evaluate("document.cookie.includes('fixture_marker=normal') && localStorage.getItem('fixture_marker')==='normal'")
 existing={row['id'] for row in c.windows()};c.key('-M','ctrl','-M','shift','-k','n','-m','shift','-m','ctrl');private=c.wait(lambda:next((row for row in c.windows() if row['id'] not in existing),None),'actual private window');c.capture('private-window.png')
 private_url=c.server.origin+'/page?visit=private&marker=private';c.key('-M','ctrl','-k','l','-m','ctrl');c.key(private_url);c.key('-k','Return');target=c.wait(lambda:next((row for row in c.targets() if row.get('url')==private_url),None),'actual private target');assert target.get('browserContextId') and target.get('browserContextId')!=c.original_target.get('browserContextId')
 session=c.attach(target['targetId']);read=lambda expression:c.read_session(expression,session)
 c.wait(lambda:read('document.readyState')=='complete','private local page');assert read("document.cookie==='' && localStorage.getItem('fixture_marker')===null")
 c.click_expression("document.querySelector('#set-marker')",read=read,window=private);c.wait(lambda:read("document.cookie.includes('fixture_marker=private') && localStorage.getItem('fixture_marker')==='private'"),'private independent storage');c.key('-M','ctrl','-M','shift','-k','w','-m','shift','-m','ctrl');c.wait(lambda:all(row['id']!=private['id'] for row in c.windows()),'private window close');assert c.evaluate("document.cookie.includes('fixture_marker=normal') && localStorage.getItem('fixture_marker')==='normal'");c.checks.append('Native private window has distinct browser context and isolated real cookies/local storage')
 sentinel=c.server.origin+'/page?visit=after-private';c.navigate(sentinel);c.wait(lambda:c.evaluate('location.href')==sentinel,'post-private normal visit');c.navigate('brave://history');observed=c.wait(lambda:history_ui() if sentinel in (history_ui() or []) else None,'actual history provider after private window close');(c.out/'history-provider-observed.json').write_text(json.dumps(dict(normal=normal,private=private_url,sentinel=sentinel,rows=observed),indent=2));assert private_url not in observed and normal in observed;c.capture('private-history-isolation.png');c.click_accessible(c.wait(lambda:control('Brave',description='Customize and control Brave'),'actual captured application menu button'));exit_control=c.wait(lambda:control('Exit','menu item'),'actual browser Exit menu item');c.click_accessible(exit_control);c.wait(c.browser_exited,'native browser quit and profile flush');persisted=history_urls(c.profile);assert normal in persisted and sentinel in persisted and private_url not in persisted;c.checks.append('Private visit remains absent from actual normal history UI and durable history after native quit')
 (c.out/'library-outcomes.json').write_text(json.dumps(dict(added=added,edited=edited,removedId=added['id'],privateWindow=private,privateTarget=target,normalHistory=persisted,providerHistory=observed),indent=2))
